  status: string;
  submitted_at: string | null;
  return_count: number;
};
type Rule = {
  expected: readonly string[];
  next?: string;
  audit: string;
  entity: string;
  fields: readonly string[];
};

const RULES: Record<string, Rule> = {
  admit: {
    expected: ['TRIAGEM_ADMISSIBILIDADE'],
    next: 'ADMITIDO',
    audit: 'INF_RAIT_CASE_ADMIT',
    entity: 'inf.rait_case',
