            }
          }
        },
        "recipe_name": {},
        "recipe_variant": {},
        "prompt_composition_id": {},
        "max_iterations": {},
        "capabilities": {},
        "role": {},
        "instructions_ref": {},
        "completion_evidence": {},
        "timeout_behavior": {},
        "child_task_ids": {},
        "dependencies": {},
        "failure_policy": {}
      },
      "oneOf": [
        {
          "$ref": "#/$defs/routineExecutor",
          "properties": {
            "kind": {
              "const": "routine"
            }
          }
        },
        {
          "$ref": "#/$defs/agentExecutor",
          "properties": {
            "kind": {
              "const": "agent"
            }
          }
        },
        {
          "$ref": "#/$defs/humanExecutor",
