          },
          "started_at": {
            "type": "string",
            "format": "date-time"
          },
          "ended_at": {
            "type": ["string", "null"],
            "format": "date-time"
          },
          "verdict": {
            "enum": ["PASS", "REVIEW", "FAIL", "RGR", "ESCALATED"]
          },
          "hard_gate_failures": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "soft_gate_failures": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "evidence_refs": {
            "type": "array",
            "uniqueItems": true,
            "items": {
              "type": "string",
              "pattern": "^EV-"
            }
          }
        }
      }
    },
    "priority": {
      "type": "integer",
      "minimum": 0,
      "maximum": 100
    },
    "tags": {
      "type": "array",
      "uniqueItems": true,
