#!/usr/bin/env node
import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { format } from '../../node_modules/prettier/index.mjs';
import { parseCatalogue } from './parser.mjs';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '../..');
const args = process.argv.slice(2);
const value = (name, fallback) => {
  const i = args.indexOf(name);
  return i >= 0 ? args[i + 1] : fallback;
};
const source = resolve(
  value('--source', join(root, 'docs/framework/arch/parameter-catalogue.md')),
);
const out = resolve(value('--out-dir', root));
const customOutput = args.includes('--out-dir');
function sql(value) {
  return `'${String(value).replaceAll("'", "''")}'`;
}
function sqlJson(value) {
  return sql(JSON.stringify(value));
}
function renderSeed(model) {
  const rows = model.entries
    .map(
      (entry) =>
        `(${sql('00000000-0000-7000-8000-00000000a001')}, NULL, 'tenant', ${sql(entry.surface)}, ${sql(entry.key)}, ${sqlJson(entry.value_json)}, ${sql(entry.value_type)}, ${sql(entry.status)}, ${entry.source_pending}, ${entry.legal_readonly}, ${sql(entry.decision_ref)}, NULL, 'ARCH-PARAMETER-CATALOGUE', 1, '2026-09-13', ${sql('00000000-0000-4000-8000-0000b0000016')}, now())`,
    )
    .join(',\n');
  return `-- Generated from parameter-catalogue.md sha256:${model.sourceHash}\n-- Applied by backend/database/seed.sh after apply.sh: the tenant context below satisfies auth.enforce_tenant_id().\nselect set_config('app.role', 'owner', false);\nselect set_config('app.tenant_id', '00000000-0000-7000-8000-00000000a001', false);\nINSERT INTO ops.parameter\n  (tenant_id, traffic_agency_id, scope, surface, key, value_json, value_type, status, source_pending, legal_readonly, decision_ref, legal_basis, reason, version, effective_from, changed_by, created_at)\nVALUES\n${rows}\nON CONFLICT (tenant_id, coalesce(traffic_agency_id, '00000000-0000-0000-0000-000000000000'::uuid), surface, key, effective_from) DO NOTHING;\n`;
}
function renderCatalogue(model) {
  const entries = model.entries.map(({ line, ...entry }) => ({
    ...entry,
    provenance: { line },
  }));
  return `// Generated from parameter-catalogue.md sha256:${model.sourceHash}\nexport const PARAMETER_CATALOGUE_SOURCE_SHA256 = '${model.sourceHash}';\nexport const PARAMETER_CATALOGUE = ${JSON.stringify(entries, null, 2)} as const;\n`;
}
function renderFlags(model) {
  const flags = Object.fromEntries(
    model.entries
      .filter((entry) => entry.value_type === 'F' && !entry.legal_readonly)
      .map((entry) => [entry.key, entry.value_json]),
  );
  return `// Generated from parameter-catalogue.md sha256:${model.sourceHash}\nexport const PARAMETER_FLAGS_SOURCE_SHA256 = '${model.sourceHash}';\nexport const PARAMETER_FLAGS = ${JSON.stringify(flags, null, 2)} as const;\n`;
}
async function atomic(path, content) {
  await mkdir(dirname(path), { recursive: true });
  try {
    if ((await readFile(path, 'utf8')) === content) return;
  } catch {}
  const temp = `${path}.tmp-${process.pid}`;
  await writeFile(temp, content);
  await rename(temp, path);
}
async function formatTypeScript(content) {
  return format(content, {
    parser: 'typescript',
    singleQuote: true,
    trailingComma: 'all',
  });
}
try {
  const model = await parseCatalogue(source);
  await atomic(
    customOutput
      ? join(out, '05-parameters.sql')
      : join(root, 'backend/database/seed/05-parameters.sql'),
    renderSeed(model),
  );
  const cataloguePath = customOutput
    ? join(out, 'parameter-catalogue.ts')
    : join(
        root,
        'backend/domains/ops/parameter/src/generated/parameter-catalogue.ts',
      );
  const flagsPath = customOutput
    ? join(out, 'parameter-flags.ts')
    : join(root, 'backend/app/src/generated/parameter-flags.ts');
  await atomic(cataloguePath, await formatTypeScript(renderCatalogue(model)));
  await atomic(flagsPath, await formatTypeScript(renderFlags(model)));
} catch (error) {
  console.error(error instanceof Error ? error.message : error);
  process.exitCode = 1;
}

import { readFile, readdir } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { fileURLToPath } from 'node:url';

const TABLES = {
  RAIT: ['rait', ['rait.', 'collection.', 'deadline.', 'session.']],
  TEAT: ['teat', ['teat.', 'sync.']],
  PORTAL: ['portal', ['portal.', 'privacy.']],
  BOAT: ['est', ['est.']],
  DASHBOARD: ['dashboard', ['dashboard.']],
};
const HEADERS = [
  'Chave',
  'Tipo',
  'Default',
  'Status',
  'pend.',
  'legal',
  'Decisão',
  'Consumidor',
];
const REFS = /\b(?:H\.\d+|OD-[A-Z0-9-]+|DT-[A-Z0-9-]+)\b/g;
const COMPACT_RANGE =
  /\b(H\.\d+|(?:OD|DT)-[A-Z0-9-]+)\s*(?:…|\.\.\.)\s*(H\.\d+|(?:OD|DT)-[A-Z0-9-]+|[A-Z]+-?\d+|\d+)\b/g;
const KNOWLEDGE_BASE = new URL(
  '../../docs/meta/knowledge-base/',
  import.meta.url,
);

function clean(value) {
  return value
    .replace(/!?(?:\[([^\]]+)\]\([^)]*\))/g, '$1')
    .replace(/`|\*\*/g, '')
    .trim();
}
function cells(line) {
  const body = line.trim().replace(/^\|/, '').replace(/\|$/, '');
  const result = [];
  let current = '';
  let escaped = false;
  for (const char of body) {
    if (char === '|' && escaped) {
      current = `${current.slice(0, -1)}|`;
    } else if (char === '|') {
      result.push(current);
      current = '';
    } else {
      current += char;
      escaped = char === '\\' && !escaped;
      continue;
    }
    escaped = false;
  }
  result.push(current);
  return result.map(clean);
}
function jsonDefault(type, raw, pending) {
  if (type === 'F') {
    if (raw !== 'true' && raw !== 'false')
      throw new Error('flag default must be true or false');
    return raw === 'true';
  }
  if (/^-?(?:0|[1-9]\d*)(?:\.\d+)?(?:[eE][+-]?\d+)?$/.test(raw)) {
    const value = Number(raw);
    if (!Number.isFinite(value))
      throw new Error('numeric default must be finite');
    return value;
  }
  if (raw === '—') {
    if (!pending) throw new Error('em dash requires pend.=sim');
    return null;
  }
  return raw;
}

function hasExactKeys(value, keys) {
  return (
    value !== null &&
    typeof value === 'object' &&
    !Array.isArray(value) &&
    Object.keys(value).length === keys.length &&
    keys.every((key) => Object.hasOwn(value, key))
  );
}

function legalBasesDefault(type, raw) {
  if (type !== 'json') throw new Error('legal bases type must be json');
  let value;
  try {
    value = JSON.parse(raw);
  } catch {
    throw new Error('legal bases default must be valid JSON');
  }
  if (
    !hasExactKeys(value, [
      'schemaVersion',
      'policyCode',
      'basisRanks',
      'noneRank',
      'postProtocolRevision',
    ]) ||
    value.schemaVersion !== 1 ||
    value.policyCode !== 'ADR-0024-2026-09-16' ||
    !hasExactKeys(value.basisRanks, ['pcd', 'age_80_plus', 'age_60_plus']) ||
    value.basisRanks.pcd !== 2 ||
    value.basisRanks.age_80_plus !== 2 ||
    value.basisRanks.age_60_plus !== 1 ||
    value.noneRank !== 0 ||
    value.postProtocolRevision !== 'forbidden'
  )
    throw new Error('legal bases default must match the approved schema');
  return value;
}

function numericReference(reference) {
  const match = reference.match(/^(.*?)(\d+)$/);
  if (!match) return undefined;
  return { prefix: match[1], digits: match[2] };
}

function compactRange(start, end) {
  const first = numericReference(start);
  if (!first) return undefined;

  const completeEnd = /^(?:H\.\d+|(?:OD|DT)-[A-Z0-9-]+)$/.test(end);
  const last = numericReference(end);
  if (!last) return undefined;
  if (completeEnd && first.prefix !== last.prefix) return undefined;
  if (!completeEnd && last.prefix && !first.prefix.endsWith(last.prefix))
    return undefined;

  const firstNumber = Number(first.digits);
  const lastNumber = Number(last.digits);
  if (!Number.isSafeInteger(firstNumber) || !Number.isSafeInteger(lastNumber))
    return undefined;
  if (lastNumber < firstNumber) return undefined;

  return {
    prefix: first.prefix,
    first: firstNumber,
    last: lastNumber,
    width: Math.max(first.digits.length, last.digits.length),
  };
}

function expandCompactReferences(text) {
  const references = new Set(text.match(REFS) ?? []);
  for (const match of text.matchAll(COMPACT_RANGE)) {
    const range = compactRange(match[1], match[2]);
    if (!range) continue;
    for (let value = range.first; value <= range.last; value += 1)
      references.add(
        `${range.prefix}${String(value).padStart(range.width, '0')}`,
      );

    let trailing = text.slice((match.index ?? 0) + match[0].length);
    let suffix = trailing.match(/^\s*,\s*([A-Z]+-?\d+)/);
    while (suffix) {
      const expanded = compactRange(match[1], suffix[1]);
      if (expanded && expanded.first === expanded.last)
        references.add(
          `${expanded.prefix}${String(expanded.first).padStart(expanded.width, '0')}`,
        );
      trailing = trailing.slice(suffix[0].length);
      suffix = trailing.match(/^\s*,\s*([A-Z]+-?\d+)/);
    }
  }
  return references;
}

async function ownerBallotPaths(directory) {
  const paths = [];
  for (const entry of await readdir(directory, { withFileTypes: true })) {
    const path = `${directory}/${entry.name}`;
    if (entry.isDirectory()) paths.push(...(await ownerBallotPaths(path)));
    else if (entry.isFile() && entry.name.endsWith('.md')) paths.push(path);
  }
  return paths.sort();
}

async function decisionReferences() {
  const sourcePaths = [
    fileURLToPath(new URL('decision-closure-plan.md', KNOWLEDGE_BASE)),
    fileURLToPath(new URL('steering.md', KNOWLEDGE_BASE)),
    fileURLToPath(new URL('open-decisions-rait.md', KNOWLEDGE_BASE)),
    fileURLToPath(new URL('open-issues.md', KNOWLEDGE_BASE)),
    ...(await ownerBallotPaths(
      fileURLToPath(new URL('owner-ballots/', KNOWLEDGE_BASE)),
    )),
  ];
  const texts = await Promise.all(
    sourcePaths.map((path) => readFile(path, 'utf8')),
  );
  return expandCompactReferences(texts.join('\n'));
}

function headingRows(lines, source) {
  const headings = new Map();
  for (let index = 0; index < lines.length; index += 1) {
    const heading = lines[index].match(
      /^##\s+(RAIT|TEAT|PORTAL|BOAT|DASHBOARD)\b/,
    )?.[1];
    if (!heading) continue;
    if (headings.has(heading))
      throw new Error(
        `${source}:${index + 1}: duplicate catalogue heading ${heading}`,
      );
    headings.set(heading, index);
  }
  for (const heading of Object.keys(TABLES))
    if (!headings.has(heading))
      throw new Error(`${source}: catalogue table missing for ${heading}`);
  return headings;
}

export async function parseCatalogue(source) {
  const bytes = await readFile(source);
  const text = bytes.toString('utf8');
  const lines = text.split(/\r?\n/);
  const entries = [];
  const seen = new Set();
  const headings = headingRows(lines, source);
  const orderedHeadings = [...headings.entries()].sort(
    ([, left], [, right]) => left - right,
  );
  for (const [heading, index] of orderedHeadings) {
    const nextHeading = lines.findIndex(
      (line, lineIndex) => lineIndex > index && /^##\s+/.test(line),
    );
    const end = nextHeading < 0 ? lines.length : nextHeading;
    let row = index + 1;
    while (row < end && !lines[row].trim().startsWith('|')) row += 1;
    if (row >= end) throw new Error(`${source}:${index + 1}: table missing`);
    const header = cells(lines[row]);
    if (
      header.length !== HEADERS.length ||
      header.some((value, i) => value !== HEADERS[i])
    )
      throw new Error(
        `${source}:${row + 1}: header must be ${HEADERS.join('|')}`,
      );
    const separator = cells(lines[row + 1] ?? '');
    if (
      separator.length !== 8 ||
      separator.some((value) => !/^:?-{3,}:?$/.test(value))
    )
      throw new Error(`${source}:${row + 2}: separator must have eight cells`);
    row += 2;
    while (row < lines.length && lines[row].trim().startsWith('|')) {
      const values = cells(lines[row]);
      if (values.length !== 8 || values.some((value) => value === ''))
        throw new Error(
          `${source}:${row + 1}: malformed or empty catalogue row`,
        );
      const [
        key,
        type,
        defaultText,
        status,
        pendingText,
        legalText,
        decision,
        consumer,
      ] = values;
      if (seen.has(key))
        throw new Error(`${source}:${row + 1}: duplicate key ${key}`);
      seen.add(key);
      const [surface, prefixes] = TABLES[heading];
      if (!prefixes.some((prefix) => key.startsWith(prefix)))
        throw new Error(`${source}:${row + 1}: incompatible prefix for ${key}`);
      if (!['vigente', 'a_confirmar', 'proposta'].includes(status))
        throw new Error(`${source}:${row + 1}: invalid status`);
      if (
        !['sim', 'não'].includes(pendingText) ||
        !['sim', 'não'].includes(legalText)
      )
        throw new Error(`${source}:${row + 1}: invalid boolean cell`);
      const sourcePending = pendingText === 'sim';
      const tokens = decision.match(REFS) ?? [];
      const selected =
        tokens.filter((token) => /^H\./.test(token)).at(-1) ??
        tokens.find((token) => /^(?:OD|DT)-/.test(token));
      if (!selected)
        throw new Error(`${source}:${row + 1}: decision reference missing`);
      let value_json;
      try {
        value_json =
          key === 'rait.priority.legal_bases'
            ? legalBasesDefault(type, defaultText)
            : jsonDefault(type, defaultText, sourcePending);
      } catch (error) {
        throw new Error(`${source}:${row + 1}: ${key}: ${error.message}`);
      }
      entries.push({
        key,
        value_type: type,
        value_json,
        status,
        source_pending: sourcePending,
        legal_readonly: legalText === 'sim',
        decision_ref: selected,
        decision_tokens: tokens,
        consumer,
        surface,
        line: row + 1,
      });
      row += 1;
    }
    if (lines.slice(row, end).some((line) => line.trim().startsWith('|')))
      throw new Error(`${source}:${row + 1}: multiple tables for ${heading}`);
  }
  const resolvedDecisions = await decisionReferences();
  for (const entry of entries)
    for (const token of entry.decision_tokens) {
      if (!resolvedDecisions.has(token))
        throw new Error(
          `${source}:${entry.line}: unresolved decision ${token}`,
        );
    }
  return {
    source,
    sourceHash: createHash('sha256').update(bytes).digest('hex'),
    entries,
  };
}

import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { execFile } from 'node:child_process';
import { mkdir, mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { promisify } from 'node:util';
import test from 'node:test';
import { parseCatalogue } from '../parser.mjs';

const exec = promisify(execFile);
const root = resolve(dirname(fileURLToPath(import.meta.url)), '../../..');
const fixture = join(root, 'tools/parameters/fixtures/minimal-catalogue.txt');
const generator = join(root, 'tools/parameters/generate-seed.mjs');
const verifier = join(root, 'tools/parameters/verify.mjs');

async function run(script, args = []) {
  try {
    const result = await exec(process.execPath, [script, ...args], {
      cwd: root,
      env: { ...process.env, NODE_ENV: 'test' },
    });
    return { status: 0, stdout: result.stdout, stderr: result.stderr };
  } catch (error) {
    return {
      status: typeof error.code === 'number' ? error.code : 1,
      stdout: error.stdout ?? '',
      stderr: error.stderr ?? String(error),
    };
  }
}

async function temporarySource(mutator = (value) => value) {
  const directory = await mkdtemp('/tmp/detran-parameter-');
  const source = join(directory, 'catalogue.md');
  const original = await readFile(fixture, 'utf8');
  await writeFile(source, mutator(original), 'utf8');
  return { directory, source };
}

const legalBases = {
  schemaVersion: 1,
  policyCode: 'ADR-0024-2026-09-16',
  basisRanks: { pcd: 2, age_80_plus: 2, age_60_plus: 1 },
  noneRank: 0,
  postProtocolRevision: 'forbidden',
};

function withLegalBases(value, defaultText = JSON.stringify(legalBases)) {
  const anchor =
    '| `rait.pool.limit` | N | 12 | vigente | não | não | OD-001 | worklist |';
  assert.ok(value.includes(anchor), 'minimal catalogue fixture changed');
  return value.replace(
    anchor,
    `${anchor}\n| \`rait.priority.legal_bases\` | json | \`${defaultText}\` | vigente | não | não | OD-016 | ordering |`,
  );
}

test('dado legal_bases JSON exato quando analisar então preserva objeto tipado, schema e proveniência', async () => {
  const temporary = await temporarySource(withLegalBases);
  try {
    const model = await parseCatalogue(temporary.source);
    const row = model.entries.find(
      (entry) => entry.key === 'rait.priority.legal_bases',
    );
    assert.ok(row, 'legal_bases row must be collected');
    assert.deepEqual(row.value_json, legalBases);
    assert.equal(row.value_type, 'json');
    assert.equal(row.status, 'vigente');
    assert.equal(row.source_pending, false);
    assert.equal(row.legal_readonly, false);
    assert.equal(row.decision_ref, 'OD-016');
    assert.deepEqual(row.decision_tokens, ['OD-016']);
    assert.equal(row.surface, 'rait');
    assert.equal(row.consumer, 'ordering');
    assert.equal(
      model.sourceHash,
      createHash('sha256')
        .update(await readFile(temporary.source))
        .digest('hex'),
    );
    const output = join(temporary.directory, 'out');
    const generated = await run(generator, [
      '--source',
      temporary.source,
      '--out-dir',
      output,
    ]);
    assert.equal(generated.status, 0, generated.stderr);
    const seed = await readFile(join(output, '05-parameters.sql'), 'utf8');
    assert.ok(
      seed.includes(
        `'rait.priority.legal_bases', '${JSON.stringify(legalBases)}'`,
      ),
      'seed must contain a JSON object value rather than a JSON string',
    );
    const catalogue = await readFile(
      join(output, 'parameter-catalogue.ts'),
      'utf8',
    );
    assert.match(
      catalogue,
      /key: 'rait\.priority\.legal_bases',[\s\S]*?value_json: \{/,
    );
  } finally {
    await rm(temporary.directory, { recursive: true, force: true });
  }
});

for (const [name, defaultText] of [
  ['JSON malformado', '{"schemaVersion":1,'],
  ['array em vez de objeto', '[]'],
  ['string em vez de objeto', '"not an object"'],
  ['objeto sem campos obrigatórios', '{}'],
  [
    'rank ou política divergente',
    JSON.stringify({
      ...legalBases,
      basisRanks: { ...legalBases.basisRanks, pcd: 1 },
    }),
  ],
  [
    'campo extra não autorizado',
    JSON.stringify({ ...legalBases, allowRevision: true }),
  ],
]) {
  test(`dado legal_bases com ${name} quando analisar então rejeita a linha`, async () => {
    const temporary = await temporarySource((value) =>
      withLegalBases(value, defaultText),
    );
    try {
      await assert.rejects(
        parseCatalogue(temporary.source),
        (error) =>
          error.message.includes(temporary.source) &&
          error.message.includes('rait.priority.legal_bases'),
      );
    } finally {
      await rm(temporary.directory, { recursive: true, force: true });
    }
  });
}

test('dado legal_bases acrescentada quando gerar então defaults e metadados das demais chaves permanecem', async () => {
  const baseline = await temporarySource();
  const augmented = await temporarySource((value) =>
    withLegalBases(
      value.replace(
        '| `rait.source.pending` | S |',
        '| `rait.ladder.B` | json | 50/75/90 % | vigente | não | não | OD-006 | radar |\n| `rait.source.pending` | S |',
      ),
    ),
  );
  try {
    const before = await parseCatalogue(baseline.source);
    const after = await parseCatalogue(augmented.source);
    for (const entry of before.entries) {
      const counterpart = after.entries.find((row) => row.key === entry.key);
      assert.ok(counterpart, `missing preserved key ${entry.key}`);
      const { line: _beforeLine, ...beforeSemantics } = entry;
      const { line: _afterLine, ...afterSemantics } = counterpart;
      assert.deepEqual(afterSemantics, beforeSemantics);
    }
    assert.equal(
      after.entries.find((entry) => entry.key === 'rait.ladder.B')?.value_json,
      '50/75/90 %',
    );
    assert.equal(
      after.entries.find((entry) => entry.key === 'rait.pool.limit')
        ?.value_json,
      12,
    );
    assert.equal(
      after.entries.find((entry) => entry.key === 'teat.speed_meters')
        ?.value_json,
      false,
    );
    assert.equal(
      after.entries.find((entry) => entry.key === 'portal.card_payment')
        ?.value_json,
      'off',
    );
    assert.equal(
      after.entries.find((entry) => entry.key === 'rait.source.pending')
        ?.value_json,
      null,
    );
    const baselineOutput = join(baseline.directory, 'out');
    const augmentedOutput = join(augmented.directory, 'out');
    for (const [source, output] of [
      [baseline.source, baselineOutput],
      [augmented.source, augmentedOutput],
    ]) {
      const result = await run(generator, [
        '--source',
        source,
        '--out-dir',
        output,
      ]);
      assert.equal(result.status, 0, result.stderr);
    }
    const beforeSeed = await readFile(
      join(baselineOutput, '05-parameters.sql'),
      'utf8',
    );
    const afterSeed = await readFile(
      join(augmentedOutput, '05-parameters.sql'),
      'utf8',
    );
    for (const entry of before.entries) {
      const beforeLine = beforeSeed
        .split('\n')
        .find((line) => line.includes(`'${entry.key}'`));
      const afterLine = afterSeed
        .split('\n')
        .find((line) => line.includes(`'${entry.key}'`));
      assert.ok(beforeLine, `missing original seed row ${entry.key}`);
      assert.equal(afterLine, beforeLine, `seed row changed for ${entry.key}`);
    }
  } finally {
    await rm(baseline.directory, { recursive: true, force: true });
    await rm(augmented.directory, { recursive: true, force: true });
  }
});

